      "position": "Upper-middle",
      "scene": "The entrance to the lush jungle ruins, the dark cave entrance formed by ancient stone pillars carved with crescent symbols and covered with vines.",
      "action": "The girl cautiously approached from a three-quarters perspective from behind, while simultaneously reading the map.",
      "props": [
        "map",
        "Abandoned cave entrance",
        "Dense vegetation"
      ],
      "text": {
        "speech": "{argument name=\"panel 2 speech\" default=\"The treasure should be just ahead...!\"}",
        "sound_effect": "rustling sound"
